(m.Word(particle+0x10)),N.Word(m.Word(node+0x18))).Store(),oldZ=N.Mul(N.Word(m.Word(particle+0x18)),N.Word(m.Word(node+0x18))).Store();uint vx=N.Add(N.Word(m.Word(particle+0x10)),N.Mul(N.Word(impulse),N.Word(normal[0]))).Store();m.Word(particle+0x10,vx);uint vz=N.Add(N.Mul(N.Word(impulse),N.Word(normal[2])),N.Word(m.Word(particle+0x18))).Store();m.Word(particle+0x18,vz);uint newZ=N.Mul(N.Word(vz),N.Word(m.Word(node+0x18))).Store(),newX=N.Mul(N.Word(m.Word(particle+0x10)),N.Word(m.Word(node+0x18))).Store();m.Word(particle,N.Sub(N.Word(m.Word(particle)),N.Sub(N.Word(newX),N.Word(oldX))).Store());m.Word(particle+8,N.Sub(N.Word(m.Word(particle+8)),N.Sub(N.Word(newZ),N.Word(oldZ))).Store());Recycle(m,node);}}public static void Process(SoundSetupImage m,int bank){PtlAttachmentRetirementExact.Process(m,bank,delegate(SoundSetupImage image,uint node,uint head){if(image.Word(node+8)==5)Quadratic(image,node,head);else if(image.Word(node+8)==6)Plane(image,node);else throw new ArgumentException("Unexpected remaining branch.");});}}}
